/* One glyph: metrics plus where its bitmap sits in the font blob.
 * Field order packs into exactly 12 bytes on 16/32/64-bit targets, which the
 * compile-time assertion below checks. */
typedef struct tf_glyph_s {
    uint32_t rune;           /* code point                        */
    uint16_t bitmap_offset;  /* index into tf_font_t::bitmaps     */
    uint8_t  width;          /* bitmap box, in pixels             */
    uint8_t  height;
    uint8_t  x_advance;      /* pen advance, in pixels            */
    uint8_t  bitmap_length;  /* bytes at bitmap_offset            */
    int8_t   x_offset;       /* box left edge relative to the pen */
    int8_t   y_offset;       /* box top relative to the baseline;
                              *   negative is above the baseline  */
} tf_glyph_t;

/* A font: global metrics plus the two tables the generator emits. */
typedef struct tf_font_s {
    int8_t            bbox[4];      /* max width, max height, min x, min y */
    uint16_t          glyph_count;
    uint8_t           y_advance;    /* line advance, in pixels             */
    const tf_glyph_t *glyphs;       /* glyph_count entries, sorted by rune */
    const uint8_t    *bitmaps;      /* packed bitmap blob                  */
} tf_font_t;

